// 语法练：K12 语法专项（小学 / 初中 / 高中）
//  - 选级别后展示该级别全部「语法知识点」及待练题目数量，并有「AI 综合练」按钮；
//  - 点具体知识点 → 开启该知识点题库训练；
//  - AI 综合练 → 在对应及以下级别每个知识点随机抽 3 道未练过的题组卷；
//  - 同一知识点连续答对 10 题不再推送；之前答错的推送其前置题与关联题；前置已掌握则不推送前置题。


const GRAMMAR_STAGES = ['小学', '初中', '高中'];
const GRAMMAR_LV = { 小学: 1, 初中: 2, 高中: 3 };
const GRAMMAR_URL = '/data/ai/grammar.json?v=20260916a';

let GRAMMAR_DATA = null;
let gStage = '初中';

function grammarFmt(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])); }

function grammarLoad() {
  if (GRAMMAR_DATA) return Promise.resolve(GRAMMAR_DATA);
  return safeFetch(GRAMMAR_URL).then((r) => r.json()).then((d) => { GRAMMAR_DATA = d; return d; });
}

const __mod_aigrammar = {
  render({ view, APP, ctx }) {
    view.innerHTML = '<div class="card">' + IC.book + '正在加载语法题库…</div>';
    grammarLoad().then((data) => {
      if (!data || !data.items || !data.items.length) {
        view.innerHTML = '<div class="card">语法题库为空。</div>';
        return;
      }
      grammarRenderMenu(view, APP, ctx, data);
    }).catch((e) => {
      console.error(e);
      view.innerHTML = '<div class="card">语法题库加载失败：' + grammarFmt(e.message || e) + '</div>';
    });
  },
};

function grammarRenderMenu(view, APP, ctx, data) {
  const p = APP.progress;
  const g = p.aiGrammar || (p.aiGrammar = { today: {}, total: 0, wrong: 0, kp: {}, done: {} });
  const done = g.done || (g.done = {});
  const kpStat = g.kp || (g.kp = {});

  // 该级别知识点分组
  const items = data.items.filter((x) => x.stage === gStage);
  const kpMap = {};
  for (const it of items) (kpMap[it.kp] = kpMap[it.kp] || []).push(it);
  const kps = Object.keys(kpMap).map((k) => {
    const arr = kpMap[k];
    const doneN = arr.filter((x) => done[x.id]).length;
    return { kp: k, total: arr.length, pending: arr.length - doneN, doneN };
  }).sort((a, b) => b.pending - a.pending || a.kp.localeCompare(b.kp, 'zh'));

  const seg = GRAMMAR_STAGES.map((s) => `<button class="seg-btn ${s === gStage ? 'on' : ''}" data-st="${s}">${s}</button>`).join('');

  view.innerHTML = `
    <div class="section-title">${IC.zap}语法练</div>
    <div class="card">
      <div class="seg">${seg}</div>
      <button class="btn block mt" id="aiComprehensive">${IC.rotateSm}AI 综合练（${gStage} 及更低级别随机组卷）</button>
      <p class="hint">AI 综合练：在「${gStage}」及更低级别每个知识点随机抽 3 道未练过的题组卷；同一知识点连续答对 10 题后不再推送，答错的题会优先回练其前置与关联题。</p>
    </div>
    <div class="section-title">${gStage} · 语法知识点（待练 ${kps.reduce((s, k) => s + k.pending, 0)}）</div>
    <div class="ai-kp-list">
      ${kps.map((k) => `
        <div class="ai-kp">
          <div class="ai-kp-info"><div class="ai-kp-name">${grammarFmt(k.kp)}</div><div class="ai-kp-sub">待练 ${k.pending} / 共 ${k.total} 题${k.doneN ? ` · 已练 ${k.doneN}` : ''}</div></div>
          <button class="btn soft" data-kp="${grammarFmt(k.kp)}">进入训练</button>
        </div>`).join('')}
    </div>`;

  view.querySelectorAll('.seg-btn').forEach((b) => b.onclick = () => { gStage = b.dataset.st; grammarRenderMenu(view, APP, ctx, data); });
  view.querySelector('#aiComprehensive').onclick = () => grammarStartSession(view, APP, ctx, data, grammarBuildComprehensive(data, gStage), gStage + ' · AI 综合练');
  view.querySelectorAll('.ai-kp .btn').forEach((b) => b.onclick = () => {
    const kp = b.dataset.kp;
    const arr = kpMap[kp] || [];
    grammarStartSession(view, APP, ctx, data, shuffle(arr.slice()), kp);
  });
}

function grammarBuildComprehensive(data, stage) {
  const target = GRAMMAR_LV[stage];
  const p = window.APP.progress;
  const g = p.aiGrammar || {};
  const done = g.done || {};
  const kpStat = g.kp || {};
  const pool = [];
  for (const it of data.items) {
    if (GRAMMAR_LV[it.stage] > target) continue;
    const ks = kpStat[it.kp];
    if (ks && (ks.consecutive || 0) >= 10) continue; // 已掌握不再推送
    pool.push(it);
  }
  // 每个知识点取未练过的题（最多 3），并补入该知识点历史错题以回练
  const byKp = {};
  for (const it of pool) (byKp[it.kp] = byKp[it.kp] || []).push(it);
  const out = [];
  for (const kp of Object.keys(byKp)) {
    const arr = byKp[kp].filter((x) => !done[x.id]);
    const wrongIds = (kpStat[kp] && kpStat[kp].wrongIds) || [];
    const wrongItems = byKp[kp].filter((x) => wrongIds.includes(x.id));
    const picks = shuffle(arr.slice()).slice(0, 3);
    out.push(...picks, ...wrongItems.filter((w) => !picks.includes(w)));
  }
  return shuffle(out);
}

function grammarStartSession(view, APP, ctx, data, items, title) {
  if (!items.length) { ctx.toast('该知识点暂无可练题目'); return; }
  runAiQuiz(ctx, view, {
    title: title,
    backPage: 'aigrammar',
    questions: items,
    label: (it) => it.kp || '',
    shouldSkip: (it) => {
      const ks = (APP.progress.aiGrammar && APP.progress.aiGrammar.kp || {})[it.kp];
      return ks && (ks.consecutive || 0) >= 10;
    },
    preOf: (it) => {
      if (!it.pre || it.pre === '无') return null;
      const ks = (APP.progress.aiGrammar && APP.progress.aiGrammar.kp || {})[it.pre];
      if (ks && (ks.consecutive || 0) >= 10) return null; // 前置已掌握不推送
      return data.items.filter((x) => x.kp === it.pre);
    },
    relatedOf: (it) => data.items.filter((x) => x.kp === it.kp && x.id !== it.id),
    onAnswer: (it, correct) => {
      const g = APP.progress.aiGrammar || (APP.progress.aiGrammar = { today: {}, total: 0, wrong: 0, kp: {}, done: {} });
      aiBumpToday(g);
      g.total = (g.total || 0) + 1;
      if (!correct) g.wrong = (g.wrong || 0) + 1;
      g.done = g.done || {}; g.done[it.id] = true;
      const kp = g.kp || (g.kp = {});
      const ks = kp[it.kp] || (kp[it.kp] = { consecutive: 0, wrongIds: [] });
      if (correct) ks.consecutive = (ks.consecutive || 0) + 1;
      else { ks.consecutive = 0; if (!ks.wrongIds.includes(it.id)) ks.wrongIds.push(it.id); aiRecordWrong(it, 'grammar'); }
    },
  });
}


// 单词练：小学 / 初中 / 高中 词汇记忆练习
//  - 选级别后设置练习题数（默认 100）；
//  - 已掌握单词的对应题目不推送；优先推已训练单词的题，其中「练过但答错」的最优先；
//  - 答对 +1 星并更新该单词 FSRS6 档（评分 / 状态），答错进入错题练并可练前置 / 关联题。



const WORD_STAGES = ['小学', '初中', '高中'];
const WORD_URL = '/data/ai/wordbank.json?v=20260916a';

let WORD_DATA = null;
let wStage = '小学';

function wordFmt(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])); }
function wordKeyOf(it) { return (it.word && String(it.word).toLowerCase()) || ('kp:' + it.kp) || ('id:' + it.id); }

function loadWord() {
  if (WORD_DATA) return Promise.resolve(WORD_DATA);
  return safeFetch(WORD_URL).then((r) => r.json()).then((d) => { WORD_DATA = d; return d; });
}

const __mod_aiword = {
  render({ view, APP, ctx }) {
    view.innerHTML = '<div class="card">' + IC.book + '正在加载单词题库…</div>';
    loadWord().then((data) => {
      if (!data || !data.items || !data.items.length) { view.innerHTML = '<div class="card">单词题库为空。</div>'; return; }
      wordRenderMenu(view, APP, ctx, data);
    }).catch((e) => {
      console.error(e);
      view.innerHTML = '<div class="card">单词题库加载失败：' + wordFmt(e.message || e) + '</div>';
    });
  },
};

function wordRenderMenu(view, APP, ctx, data) {
  const p = APP.progress;
  const ai = p.aiWord || (p.aiWord = { today: {}, total: 0, wrong: 0, trained: {}, wrongWords: [] });

  const seg = WORD_STAGES.map((s) => `<button class="seg-btn ${s === wStage ? 'on' : ''}" data-st="${s}">${s}</button>`).join('');
  const cnt = ai.lastCount || 100;

  view.innerHTML = `
    <div class="section-title">${IC.zap}单词练</div>
    <div class="card">
      <div class="seg">${seg}</div>
      <div class="num-row mt">
        <span class="num-unit">练习题数</span>
        <input type="number" id="aiCount" class="num-input" min="10" max="2000" step="10" value="${cnt}">
        <span class="num-unit">题</span>
      </div>
      <button class="btn block mt" id="aiStart">${IC.rotateSm}开始练习</button>
      <p class="hint">已掌握单词的题不推送；优先练「已训练」的单词，其中练过但答错的最优先。每答对 1 题 +1 星并更新该词 FSRS6 档状态。</p>
    </div>`;

  view.querySelectorAll('.seg-btn').forEach((b) => b.onclick = () => { wStage = b.dataset.st; wordRenderMenu(view, APP, ctx, data); });
  view.querySelector('#aiStart').onclick = () => {
    const n = Math.min(2000, Math.max(10, Math.round(Number(view.querySelector('#aiCount').value) || 100)));
    ai.lastCount = n; ai.lastStage = wStage;
    const items = wordBuildSession(data, wStage, n, APP);
    if (!items.length) { ctx.toast('该级别暂无可练单词'); return; }
    wordStartSession(view, APP, ctx, data, items, wStage + ' · 单词练');
  };
}

function wordBuildSession(data, stage, n, APP) {
  const p = APP.progress;
  const ai = p.aiWord || (p.aiWord = { today: {}, total: 0, wrong: 0, trained: {}, wrongWords: [] });
  const trained = ai.trained || (ai.trained = {});
  const wrongWords = ai.wrongWords || (ai.wrongWords = []);
  const wrongSet = new Set(wrongWords.map((w) => String(w).toLowerCase()));
  const items = data.items.filter((x) => x.stage === stage);
  const cand = [];
  for (const it of items) {
    const wk = wordKeyOf(it);
    if (p.mastered && p.mastered[wk]) continue; // 已掌握不推送
    cand.push(it);
  }
  // 优先级：练过且答错 > 练过 > 未练
  cand.sort((a, b) => wordRank(b, trained, wrongSet) - wordRank(a, trained, wrongSet));
  return cand.slice(0, n);
}
function wordRank(it, trained, wrongSet) {
  const wk = wordKeyOf(it).toLowerCase();
  if (wrongSet.has(wk)) return 2;
  if (trained[wk]) return 1;
  return 0;
}

function wordStartSession(view, APP, ctx, data, items, title) {
  runAiQuiz(ctx, view, {
    title: title,
    backPage: 'aiword',
    questions: items,
    label: (it) => (it.word ? '单词：' + it.word : it.kp),
    shouldSkip: () => false,
    preOf: (it) => {
      if (!it.pre || it.pre === '无') return null;
      return data.items.filter((x) => x.kp === it.pre);
    },
    relatedOf: (it) => data.items.filter((x) => x.kp === it.kp && x.id !== it.id),
    rateFsrs: true,   // 答完后让用户自评 Again/Hard/Good/Easy，显式写入 FSRS6 档（使 Hard/Easy 不再为死代码）
    onAnswer: (it, correct, rating) => {
      const wk = wordKeyOf(it);
      const p = APP.progress;
      const ai = p.aiWord || (p.aiWord = { today: {}, total: 0, wrong: 0, trained: {}, wrongWords: [] });
      aiBumpToday(ai);
      ai.total = (ai.total || 0) + 1;
      if (!correct) ai.wrong = (ai.wrong || 0) + 1;
      ai.trained = ai.trained || {};
      ai.trained[wk] = (ai.trained[wk] || 0) + 1;
      if (!correct) {
        ai.wrongWords = ai.wrongWords || [];
        if (!ai.wrongWords.map((w) => String(w).toLowerCase()).includes(wk.toLowerCase())) ai.wrongWords.push(wk);
        aiRecordWrong(it, 'word');
      }
      const res = recordFsrs6(wk, rating); // 更新该单词 FSRS6 档（rating 1..4 由用户自评）
      if (res.mastered) ctx.toast('🎉 ' + (it.word || wk) + ' 已判掌握！+10星');
    },
  });
}


// 错题练：练习「语法练 / 单词练」中答错的题，每次练习更新练习数据与 FSRS6 档。



const WRONG_URLS = { grammar: '/data/ai/grammar.json?v=20260916a', word: '/data/ai/wordbank.json?v=20260916a' };
const WRONG_BANK = { grammar: null, word: null };

function wrongLoadBank(cat) {
  if (WRONG_BANK[cat]) return Promise.resolve(WRONG_BANK[cat]);
  return safeFetch(WRONG_URLS[cat]).then((r) => r.json()).then((d) => { WRONG_BANK[cat] = d; return d; });
}

function wrongTodayKey() { const d = new Date(); return d.getFullYear() + '-' + (d.getMonth() + 1) + '-' + d.getDate(); }

const __mod_aiwrong = {
  render({ view, APP, ctx }) {
    const w = APP.progress.aiWrong || (APP.progress.aiWrong = {});
    w.items = w.items || {};
    w.today = w.today || {};
    w.total = w.total || 0;
    w.wrong = w.wrong || 0;
    const items = Object.keys(w.items).map((k) => Object.assign({ _key: k }, w.items[k]));
    if (!items.length) {
      view.innerHTML = `
        <div class="section-title">${IC.xSm}错题练</div>
        <div class="card" style="text-align:center">
          <div style="font-size:40px">🎉</div>
          <div class="mt">暂无错题。在「语法练 / 单词练」中答错的题会自动收录到这里，方便集中攻克。</div>
        </div>`;
      return;
    }
    const today = w.today && w.today.date === wrongTodayKey() ? w.today : null;
    view.innerHTML = `
      <div class="section-title">${IC.xSm}错题练</div>
      <div class="card">
        <div class="stat-grid">
          <div class="stat"><div class="num">${items.length}</div><div class="lab">待练错题</div></div>
          <div class="stat"><div class="num">${w.total || 0}</div><div class="lab">累计错题练习</div></div>
          <div class="stat"><div class="num warn">${w.wrong || 0}</div><div class="lab">错题练习次数</div></div>
        </div>
        <button class="btn block mt" id="aiwStart">${IC.rotateSm}开始攻克错题（${items.length}）</button>
        <p class="hint">答对 1 题 +1 星并更新 FSRS6 档；答对后该题从错题库移除。今日已练 ${today ? today.count : 0} 题。</p>
      </div>`;
    view.querySelector('#aiwStart').onclick = () => {
      const sess = shuffle(items.slice());
      // 预加载两个题库，使「练前置 / 练关联」可正常定位到对应题组
      Promise.all([wrongLoadBank('grammar'), wrongLoadBank('word')])
        .catch(() => {})
        .then(() => wrongStartSession(view, APP, ctx, sess));
    };
  },
};

function wrongStartSession(view, APP, ctx, items) {
  runAiQuiz(ctx, view, {
    title: '错题练',
    backPage: 'aiwrong',
    questions: items,
    label: (it) => (it.word ? '单词：' + it.word : it.kp || it.cat),
    shouldSkip: () => false,
    preOf: (it) => {
      if (!it.pre || it.pre === '无') return null;
      const b = WRONG_BANK[it.cat]; return b ? b.items.filter((x) => x.kp === it.pre) : null;
    },
    relatedOf: (it) => {
      const b = WRONG_BANK[it.cat]; return b ? b.items.filter((x) => x.kp === it.kp && x.id !== it.id) : null;
    },
    rateFsrs: true,   // 答完后让用户自评 Again/Hard/Good/Easy，显式写入 FSRS6 档
    onAnswer: (it, correct, rating) => {
      const p = APP.progress;
      const w = p.aiWrong || (p.aiWrong = {});
      w.items = w.items || {};
      w.today = w.today || {};
      aiBumpToday(w);
      if (!correct) w.wrong = (w.wrong || 0) + 1;
      if (it.word) {
        const res = recordFsrs6(it.word, rating); // 更新该单词 FSRS6 档（rating 1..4 由用户自评）
        if (res.mastered) ctx.toast('🎉 ' + it.word + ' 已判掌握！+10星');
      }
      if (correct && it._key && w.items[it._key]) delete w.items[it._key]; // 答对移除
    },
  });
}




function isMastered(word) {
  return !!(window.APP && window.APP.progress && window.APP.progress.mastered && window.APP.progress.mastered[word.toLowerCase()]);
}

/* ---------- 分类扩展数据（考频/词根/相似/象形）懒加载 ---------- */
let _tax = null;
let _taxPromise = null;
function loadTax() {
  if (_tax) return Promise.resolve(_tax);
  if (!_taxPromise) {
    _taxPromise = safeFetch('/data/taxonomy.json')
      .then((r) => { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
      .then((t) => { _tax = t; return t; })
      .catch((e) => { _taxPromise = null; throw e; });
  }
  return _taxPromise;
}

// 象形记精确配图清单：单词 -> vxiaozhi 助记图 URL。
// 数据来源 https://github.com/vxiaozhi/vocabulary-book-by-deepseek（已上线 https://word.vxiaozhi.com），
// 每个单词由 AI 按其词义生成一张助记图像，按「字母/单词.jpg」命名，对应精准、远优于 emoji/语义标签取图。
// 清单由 tools/build_vxiaozhi_pict.js 依据本词库与 vxiaozhi 词表交集生成（word -> 远程图 URL），这里只读取。
let _pictImgs = null; // Map<wordLower, url>
function loadPictImages() {
  if (_pictImgs) return Promise.resolve(_pictImgs);
  _pictImgs = new Map();
  return safeFetch('/data/pict_images.json?v=20260911e')
    .then((r) => (r.ok ? r.json() : {}))
    .then((obj) => { Object.entries(obj || {}).forEach(([w, url]) => _pictImgs.set(String(w).toLowerCase(), url)); return _pictImgs; })
    .catch(() => _pictImgs);
}
// 取单词的 vxiaozhi 精确助记图 URL（无则 null），供象形记优先显示
function vxImgURL(w) {
  if (!_pictImgs || !w) return null;
  return _pictImgs.get(String(w).toLowerCase()) || null;
}
// 取单词的「象形记表情图」（Unicode emoji）：来自 taxonomy.pict[w][0]。
// 仅在单词属于象形记（在 tax.pict 中有记录）时返回，否则返回 null —— 即「用象形记里的表情图兜底」，
// 不在象形记里的词不给无意义 emoji。供单词卡片/闪记在无助记图时回退显示。
function pictEmoji(w) {
  if (!w) return null;
  const lw = String(w).toLowerCase();
  if (_tax && _tax.pict && _tax.pict[lw]) return _tax.pict[lw][0];
  return null;
}

// 暴露给全局，供 ui.js 的 wordCardHTML（单词卡片/闪记共用）以及 app.js 启动钩子调用。
// 这样单词闪记缺 vxiaozhi 助记图时，会自动回退到象形记 emoji 表情图。
window.loadPictImages = loadPictImages;
window.vxImgURL = vxImgURL;
window.pictEmoji = pictEmoji;
window.loadTax = loadTax;

let _wmap = null;
function wordMap(APP) {
  if (!_wmap) {
    _wmap = new Map();
    for (const w of (APP.library.words || [])) _wmap.set(w.word.toLowerCase(), w);
  }
  return _wmap;
}
// 词库变化（如合并选中的词书）后使缓存失效，下次渲染重建
function invalidateWordMap() { _wmap = null; }
function resolveWords(APP, list) {
  const m = wordMap(APP);
  return (list || []).map((k) => m.get(String(k).toLowerCase())).filter(Boolean);
}
const FREQ_TIERS = [
  { k: 'hot', name: '高频核心', desc: '词频榜前 3000 · 考试最常考', test: (r) => r <= 3000 },
  { k: 'mid', name: '常用进阶', desc: '词频榜 3001-6000 · 阅读常客', test: (r) => r > 3000 && r <= 6000 },
  { k: 'low', name: '低频扩展', desc: '词频榜 6000 以后 · 拔高词汇', test: (r) => r > 6000 },
  { k: 'off', name: '榜外生词', desc: '未进入万词榜 · 专业/超纲词', test: () => true },
];
const PICT_ICONS = { '动物与自然': '🐻', '食物与饮品': '🍎', '人物与身体': '🧑', '物品与工具': '🔧', '活动与运动': '⚽', '旅行与地点': '✈', '情感与表情': '😀', '符号': '🔣', '图标简笔': '🖍️', '义符': '🔤', '其他': '✨' };
// 象形记总数：emoji 图记 + 线性图标简笔
function pictTotal(tax) { return Object.keys(tax.pict || {}).length + Object.keys(tax.pictIcon || {}).length; }

// 象形记（当前学习范围内）：与「所选词书 / 难度」一致的有图单词数。
// 仅统计主词库中真实存在、且通过 ctx.inScope 的单词；pictIcon 中已被 pict 收录的不重复计数。
function pictScoped(tax, APP, ctx) {
  const m = wordMap(APP);
  const cnt = (obj, skipDup) => {
    let n = 0;
    for (const w of Object.keys(obj || {})) {
      if (skipDup && tax.pict && tax.pict[w]) continue;
      const ww = m.get(String(w).toLowerCase());
      if (!ww) continue;
      if (ctx && ctx.inScope && !ctx.inScope(ww)) continue;
      n++;
    }
    return n;
  };
  return cnt(tax.pict, false) + cnt(tax.pictIcon, true);
}

// 词根记（当前学习范围内）：至少含 1 个「待练（未掌握且在范围内）」单词的词根组数
function rootsScoped(tax, APP, ctx) {
  return (tax.roots || []).filter((g) => resolveWords(APP, g.words)
    .some((w) => !isMastered(w.word) && (!ctx || !ctx.inScope || ctx.inScope(w)))).length;
}
// 线性图标简笔 SVG（phosphor 为填充型，其余为描边型，分别处理以保证都能渲染）
function iconSvg(v) {
  if (!v) return '';
  const [coll, , body, iw, ih] = v;
  const stroke = coll !== 'ph';
  return `<svg class="p-svg" viewBox="0 0 ${iw || 24} ${ih || 24}" fill="${stroke ? 'none' : 'currentColor'}" stroke="${stroke ? 'currentColor' : 'none'}" stroke-width="${stroke ? 1.8 : 0}" stroke-linecap="round" stroke-linejoin="round">${body}</svg>`;
}
// 人教版高中册顺序（与听写模块保持一致），用于单元排序与分组
const HS_BOOKS = ['必修一', '必修二', '必修三', '选必一', '选必二', '选必三', '选必四'];
function hsUnitSortKey(u) {
  if (!u) return [99, 99];
  const wm = /^(.+?)\s*Welcome\s*Unit$/i.exec(u);
  if (wm) return [HS_BOOKS.indexOf(wm[1]), -1];
  const m = /^([^U]+)U(\d+)$/.exec(u);
  if (!m) return [99, 99];
  return [HS_BOOKS.indexOf(m[1]), Number(m[2])];
}
// 收集高中各单元单词，按「册 -> 单元」分组（Welcome Unit 置于该册最前）
function hsUnitGroups(APP) {
  const byUnit = {};
  for (const w of (APP.library.words || [])) {
    const p = w.pep;
    if (p && p.band === '高中' && p.unit) (byUnit[p.unit] = byUnit[p.unit] || []).push(w);
  }
  const books = {};
  for (const u of Object.keys(byUnit)) {
    const sk = hsUnitSortKey(u);
    const m = /^(.+?)\s*Welcome\s*Unit$/i.exec(u);
    const book = m ? m[1] : (u.replace(/U\d+$/, '') || '其他');
    if (!books[book]) books[book] = { order: sk[0], units: [] };
    books[book].units.push({ unit: u, words: byUnit[u], sk });
  }
  const list = Object.keys(books).map((b) => books[b]).sort((a, b) => a.order - b.order);
  list.forEach((bk) => bk.units.sort((a, b) => a.sk[0] - b.sk[0] || a.sk[1] - b.sk[1]));
  return list;
}

// 主题分类只保留「原始语义主题」，排除后续新加词书带来的考试/词书名分类
// （如 雅思 / COCA / 牛津 / 新概念 / 专八 / 德语学习 / 程序员 / SAT / 考研 / 托福 / GRE / 专业词汇 / 英语词典 …）。
// 基准取自词库初始版本（git 早期提交）的 24 个分类，确保主题分类不被新词书污染。
const ORIGINAL_THEMES = new Set([
  '交通', '人物', '健康', '其他', '动作', '动物', '场所·家居', '天气', '学习', '家庭',
  '工作', '情绪', '描述', '数字', '文化·传统', '时间', '短语', '社会', '科技', '自然',
  '衣物·穿戴', '连接词', '颜色', '食物',
]);

const __mod_category = {
  render({ view, APP, ctx }) {
    const words = (APP.library && APP.library.words) || [];
    const groups = {};
    words.forEach((w) => {
      const cat = w.category || '未分类';
      if (!ORIGINAL_THEMES.has(cat)) return; // 仅保留原主题，排除新加词书分类
      if (!groups[cat]) groups[cat] = [];
      groups[cat].push(w);
    });
    const cats = Object.keys(groups).sort((a, b) => {
      if (a === '未分类') return 1;
      if (b === '未分类') return -1;
      return a.localeCompare(b, 'zh-CN');
    });
    if (!cats.length) {
      // 词库「核心重字段」（含 category）是分层懒加载的：还没到货时分组必然为空，
      // 此时**不能**报「词库暂无数据」（会误导用户跑去导入）—— 页面会在数据到货后自动补正。
      view.innerHTML = (APP.library && APP.library.__index && !APP._fullReady)
        ? '<div class="card">分类数据加载中…稍后自动刷新。</div>'
        : '<div class="card">词库暂无数据，请到「导入」添加单词。</div>';
      return;
    }
    // 高中分单元：统计单元数与待练数
    const hsGroups = hsUnitGroups(APP);
    let hsUnits = 0, hsActive = 0;
    hsGroups.forEach((bk) => bk.units.forEach((u) => {
      hsUnits++;
      hsActive += u.words.filter((w) => !isMastered(w.word) && ctx.inScope(w)).length;
    }));
    // 专升本专项：统计已标注 zsb 的待练词数
    let zsbActive = 0;
    for (const w of words) {
      if (w.zsb && !isMastered(w.word) && ctx.inScope(w)) zsbActive++;
    }
    const TAX_CARDS = [
      { kind: 'unit', icon: IC.bookSm, name: '单元记', desc: hsUnits + ' 个教材单元', badge: hsActive ? hsActive + ' 词待练' : '按册逐单元练' },
      { kind: 'zsb', icon: '🎓', name: '专升本专项记', desc: '升本核心词汇', badge: zsbActive ? zsbActive + ' 词待练' : '暂无待练' },
      { kind: 'pict', icon: '🧩', name: '象形记', desc: '图像联想记忆', badge: '加载中…' },
      { kind: 'roots', icon: IC.bookOpenSm, name: '词根记', desc: '词根词缀拆词', badge: '加载中…' },
      { kind: 'freq', icon: IC.chartSm, name: '考频记', desc: '按考试词频分层', badge: '加载中…' },
      { kind: 'similar', icon: IC.targetSm, name: '相似记', desc: '易混词对比记', badge: '加载中…' },
    ];
    // 顶部「范围内待练」词数：与下方主题分类卡片的口径一致（未掌握 + 在所选词书/难度范围内）
    const themeActiveCount = cats.reduce((a, c) =>
      a + groups[c].filter((w) => !isMastered(w.word) && (!ctx.inScope || ctx.inScope(w))).length, 0);
    view.innerHTML = `
      <div class="section-title"><svg class="vico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3.5" y="3.5" width="7" height="7" rx="1.6"/><rect x="13.5" y="3.5" width="7" height="7" rx="1.6"/><rect x="3.5" y="13.5" width="7" height="7" rx="1.6"/><rect x="13.5" y="13.5" width="7" height="7" rx="1.6"/></svg>分类记 · 共 ${cats.length} 个分类 / 范围内 ${themeActiveCount} 词待练（仅原主题，已过滤新加词书分类）</div>
      <div class="tax-grid">
        ${TAX_CARDS.map((c) => `
        <div class="cat-card tax-card" data-tax="${c.kind}">
          <div class="c-name">${c.icon}${c.name}</div>
          <div class="c-count">${c.desc}</div>
          <span class="badge" data-taxbadge="${c.kind}">${c.badge}</span>
        </div>`).join('')}
      </div>
      <div class="section-title" style="margin-top:18px">${IC.grid}主题分类</div>
      <div class="cat-grid">
        ${cats.map((c) => {
          const all = groups[c];
          const active = all.filter((w) => !isMastered(w.word));
          const activeDiff = active.filter((w) => ctx.inScope(w));
          const masteredCount = all.length - active.length;
          const badge = activeDiff.length ? `${activeDiff.length} 词待练` : '当前难度无待练';
          return `
          <div class="cat-card" data-cat="${escapeHtml(c)}">
            <div class="c-name">${escapeHtml(c)}</div>
            <div class="c-count">${all.length} 词${masteredCount ? ` · 已掌握 ${masteredCount}` : ''}</div>
            <span class="badge">${badge}</span>
          </div>`;
        }).join('')}
      </div>
    `;
    view.querySelectorAll('.cat-card').forEach((card) => {
      if (card.dataset.tax) {
        card.addEventListener('click', () => openTaxSub(view, ctx, APP, card.dataset.tax));
        return;
      }
      card.addEventListener('click', () => {
        const cat = card.dataset.cat;
        const active = groups[cat].filter((w) => !isMastered(w.word) && ctx.inScope(w));
        if (!active.length) { ctx.toast('该分类在当前难度下暂无待练单词 🎉'); return; }
        openCategory(view, ctx, cat, active);
      });
    });
    // 异步填充五张入口卡的统计
    loadTax().then((tax) => {
      const m = wordMap(APP);
      const act = (k) => resolveWords(APP, k).filter((w) => !isMastered(w.word) && ctx.inScope(w));
      const set = (kind, text) => {
        const el = view.querySelector(`[data-taxbadge="${kind}"]`);
        if (el) el.textContent = text;
      };
      if (!view.isConnected) return;
      // 象形记 / 词根记：与所选词书、难度联动（此前用全库总数，选定词书后数字明显偏大）
      set('pict', pictScoped(tax, APP, ctx) + ' 词有图记');
      set('roots', rootsScoped(tax, APP, ctx) + ' 组词根词缀');
      // 考频分层：off 档应为「词库中未进入词频榜」的词。
      // 旧写法 off 档用 test:()=>true 去匹配 tax.freq 的条目 → 等于把全部有排名词也算了一遍，
      // 高频/常用/低频被重复计入，总数虚高近一倍（高考3500词实测 5488，正确值 2744）。
      const fc = FREQ_TIERS.map((t) => {
        const ws = (t.k === 'off')
          ? [...m.keys()].filter((w) => !(tax.freq || {})[w])
          : Object.entries(tax.freq || {}).filter(([w, r]) => byWordIn(m, w) && t.test(r)).map(([w]) => w);
        return act(ws).length;
      }).reduce((a, b) => a + b, 0);
      set('freq', fc + ' 词待练');
      const sc = (tax.similar || []).filter((g) => act(g).length >= 2).length;
      set('similar', sc + ' 组易混词');
    }).catch(() => {
      ['pict', 'roots', 'freq', 'similar'].forEach((k) => {
        const el = view.querySelector(`[data-taxbadge="${k}"]`);
        if (el) el.textContent = '数据未加载';
      });
    });
  },
};

function byWordIn(m, w) { return m.has(w); }

/* ---------- 扩展子模块：单元记/象形记/词根记/考频记/相似记 ---------- */
function openTaxSub(view, ctx, APP, kind) {
  if (kind === 'unit') return openHSUnits(view, ctx, APP);
  if (kind === 'zsb') return renderZsb(view, ctx, APP);
  view.innerHTML = '<div class="card">分类数据加载中…</div>';
  loadTax().then((tax) => {
    if (!view.isConnected) return;
    if (kind === 'roots') renderRoots(view, ctx, APP, tax, 'all');
    else if (kind === 'similar') renderSimilar(view, ctx, APP, tax);
    else if (kind === 'freq') renderFreq(view, ctx, APP, tax);
    else if (kind === 'pict') loadPictImages().then(() => renderPictCats(view, ctx, APP, tax)).catch(() => renderPictCats(view, ctx, APP, tax));
  }).catch(() => {
    view.innerHTML = '<div class="card">扩展分类数据加载失败，请通过服务器（而非本地文件）访问后重试。</div>';
  });
}
function renderZsb(view, ctx, APP) {
  const back = backMain();
  const zsbWords = (APP.library.words || []).filter((w) => w.zsb);
  const groups = {};
  for (const w of zsbWords) {
    const L = (w.word && w.word[0] ? w.word[0] : '?').toUpperCase();
    (groups[L] = groups[L] || []).push(w);
  }
  const letters = Object.keys(groups).sort((a, b) => a.localeCompare(b));
  view.innerHTML = `
    <div class="section-title">🎓专升本专项记 · ${zsbWords.length} 词</div>
    <div class="card">
      <div class="between"><h2>专升本核心词汇</h2><button class="btn sm ghost" id="back">返回分类</button></div>
      <p class="hint" style="margin-top:4px">专升本英语词汇约 3500，对应「高中(高考) + 大学英语四级(CET-4)」水平。这里汇总词库中已标注的升本词汇，按首字母分组速记。</p>
    </div>
    <div class="cat-grid">
      ${letters.map((L) => {
        const all = groups[L];
        const act = all.filter((w) => !isMastered(w.word) && ctx.inScope(w));
        return `<div class="cat-card" data-letter="${L}">
          <div class="c-name">${L}</div>
          <div class="c-count">${all.length} 词</div>
          <span class="badge">${act.length ? act.length + ' 待练' : '已掌握'}</span>
        </div>`;
      }).join('')}
    </div>`;
  view.querySelector('#back').onclick = back;
  view.querySelectorAll('.cat-card[data-letter]').forEach((card) => {
    card.addEventListener('click', () => {
      const L = card.dataset.letter;
      const act = groups[L].filter((w) => !isMastered(w.word) && ctx.inScope(w));
      if (!act.length) { ctx.toast('该组在当前难度下暂无待练单词 🎉'); return; }
      openCategory(view, ctx, `专升本 · ${L}`, act, () => renderZsb(view, ctx, APP));
    });
  });
  view.scrollTop = 0;
}
function backMain() { return () => window.dispatchEvent(new CustomEvent('goto', { detail: 'category' })); }

function renderRoots(view, ctx, APP, tax, filter) {
  const back = backMain();
  const types = [['all', '全部'], ['pre', '前缀'], ['root', '词根'], ['suf', '后缀']];
  const list = (tax.roots || []).filter((g) => filter === 'all' || !filter || g.t === filter);
  view.innerHTML = `
    <div class="section-title">${IC.bookOpen}词根记 · ${list.length} 组</div>
    <div class="card">
      <div class="between"><h2>词根词缀 · 拆词速记</h2><button class="btn sm ghost" id="back">返回分类</button></div>
      <p class="hint" style="margin-top:4px">掌握一个词根 = 串记一族单词。数据来源：开源英语词根库（1061 条）精选 + 词库匹配。</p>
      <div class="reading-mode-bar" style="margin-top:8px">
        ${types.map(([k, n]) => `<button class="mode-btn ${filter === k ? 'on' : ''}" data-rt="${k}">${n}</button>`).join('')}
      </div>
    </div>
    <div class="cat-grid">
      ${list.map((g) => {
        const act = resolveWords(APP, g.words).filter((w) => !isMastered(w.word) && ctx.inScope(w));
        return `<div class="cat-card" data-root="${escapeHtml(g.k)}" data-cn="${escapeHtml(g.cn)}">
          <div class="c-name">${escapeHtml(g.k)} <span class="rt-type t-${g.t}">${g.t === 'pre' ? '前缀' : g.t === 'suf' ? '后缀' : '词根'}</span></div>
          <div class="c-count">${escapeHtml(g.cn)}${g.en ? ' · ' + escapeHtml(g.en) : ''}</div>
          <span class="badge">${g.words.length} 词 · 待练 ${act.length}</span>
        </div>`;
      }).join('')}
    </div>`;
  view.querySelector('#back').onclick = back;
  view.querySelectorAll('[data-rt]').forEach((b) => b.addEventListener('click', () => renderRoots(view, ctx, APP, tax, b.dataset.rt)));
  view.querySelectorAll('.cat-card[data-root]').forEach((card) => {
    card.addEventListener('click', () => {
      const g = (tax.roots || []).find((x) => x.k === card.dataset.root);
      if (!g) return;
      const act = resolveWords(APP, g.words).filter((w) => !isMastered(w.word) && ctx.inScope(w));
      if (!act.length) { ctx.toast('该词根在当前难度下暂无待练单词 🎉'); return; }
      openCategory(view, ctx, `词根 ${g.k} · ${g.cn}`, act, () => renderRoots(view, ctx, APP, tax, filter));
    });
  });
  view.scrollTop = 0;
}

function renderSimilar(view, ctx, APP, tax) {
  const back = backMain();
  const groups = (tax.similar || [])
    .map((g) => ({ g, act: resolveWords(APP, g).filter((w) => !isMastered(w.word) && ctx.inScope(w)) }))
    .filter((x) => x.act.length >= 2);
  view.innerHTML = `
    <div class="section-title">${IC.target}相似记 · ${groups.length} 组易混词</div>
    <div class="card">
      <div class="between"><h2>相似词 · 对比速记</h2><button class="btn sm ghost" id="back">返回分类</button></div>
      <p class="hint" style="margin-top:4px">拼写只差一个字母的「双胞胎词」集中对比，一遍记牢、不再混淆（编辑距离算法自动聚类）。</p>
    </div>
    <div class="cat-grid">
      ${groups.map(({ g, act }) => `
      <div class="cat-card" data-sim="${escapeHtml(g.join(','))}">
        <div class="c-name sim-names">${g.map((w) => escapeHtml(w)).join('<i class="sep">/</i>')}</div>
        <span class="badge">${g.length} 词 · 待练 ${act.length}</span>
      </div>`).join('')}
    </div>`;
  view.querySelector('#back').onclick = back;
  view.querySelectorAll('.cat-card[data-sim]').forEach((card) => {
    card.addEventListener('click', () => {
      const g = card.dataset.sim.split(',');
      const act = resolveWords(APP, g).filter((w) => !isMastered(w.word) && ctx.inScope(w));
      if (act.length < 2) { ctx.toast('这组词在当前难度下暂无可练单词 🎉'); return; }
      openCategory(view, ctx, '相似记 · ' + g.slice(0, 3).join(' / ') + (g.length > 3 ? '…' : ''), act, () => renderSimilar(view, ctx, APP, tax));
    });
  });
  view.scrollTop = 0;
}

function renderFreq(view, ctx, APP, tax) {
  const back = backMain();
  const m = wordMap(APP);
  const tiers = FREQ_TIERS.map((t) => {
    let entries;
    if (t.k === 'off') {
      entries = [...m.keys()].filter((w) => !(tax.freq || {})[w]);
      entries.sort((a, b) => ((m.get(a).difficulty || 9) - (m.get(b).difficulty || 9)) || a.localeCompare(b));
    } else {
      entries = Object.entries(tax.freq || {}).filter(([w, r]) => m.has(w) && t.test(r))
        .sort((a, b) => a[1] - b[1]).map(([w]) => w);
    }
    const act = resolveWords(APP, entries).filter((w) => !isMastered(w.word) && ctx.inScope(w));
    return { ...t, words: entries, act };
  });
  view.innerHTML = `
    <div class="section-title">${IC.chart}考频记 · 按考试词频分层</div>
    <div class="card">
      <div class="between"><h2>考频分层 · 先啃高频词</h2><button class="btn sm ghost" id="back">返回分类</button></div>
      <p class="hint" style="margin-top:4px">依据 Google 万词频榜（开源语料统计）为词库标注考频层级：排名越靠前，考试出现概率越高。</p>
    </div>
    <div class="cat-grid">
      ${tiers.map((t) => `
      <div class="cat-card" data-tier="${t.k}">
        <div class="c-name">${t.name}</div>
        <div class="c-count">${t.desc}</div>
        <span class="badge">${t.words.length} 词 · 待练 ${t.act.length}</span>
      </div>`).join('')}
    </div>`;
  view.querySelector('#back').onclick = back;
  view.querySelectorAll('.cat-card[data-tier]').forEach((card) => {
    card.addEventListener('click', () => {
      const t = tiers.find((x) => x.k === card.dataset.tier);
      if (!t) return;
      if (!t.act.length) { ctx.toast('该层级在当前难度下暂无待练单词 🎉'); return; }
      let act = t.act;
      if (act.length > 600) { act = act.slice(0, 600); ctx.toast('词量较大，本次先练前 600 词'); }
      openCategory(view, ctx, `考频记 · ${t.name}`, act, () => renderFreq(view, ctx, APP, tax));
    });
  });
  view.scrollTop = 0;
}

function renderPictCats(view, ctx, APP, tax) {
  const back = backMain();
  const m = wordMap(APP);
  // 与象形记入口卡计数保持一致：只保留主词库中存在、且在所选词书/难度范围内的单词
  const ok = (w) => { const ww = m.get(String(w).toLowerCase()); return !!ww && (!ctx.inScope || ctx.inScope(ww)); };
  const byCat = {};
  for (const [w, [e, c]] of Object.entries(tax.pict || {})) {
    if (!ok(w)) continue;
    (byCat[c] = byCat[c] || []).push([w, e]);
  }
  for (const [w] of Object.entries(tax.pictIcon || {})) {
    if (!ok(w) || tax.pict[w]) continue;
    (byCat['图标简笔'] = byCat['图标简笔'] || []).push([w, null]);
  }
  const cats = Object.keys(byCat).sort((a, b) => byCat[b].length - byCat[a].length);
  view.innerHTML = `
    <div class="section-title">🧩象形记 · ${pictScoped(tax, APP, ctx)} 词有图记（当前学习范围）</div>
    <div class="card">
      <div class="between"><h2>象形图记 · 一图记一词</h2><button class="btn sm ghost" id="back">返回分类</button></div>
      <p class="hint" style="margin-top:4px">为单词配一幅「心理图像」，图像联想是最古老的记忆术。图源：vxiaozhi AI 助记图（每个单词一张按词义精确生成的配图，已上线 word.vxiaozhi.com）优先，缺图时回退 Unicode emoji 与 Tabler/Phosphor 开源简笔图标。</p>
    </div>
    <div class="cat-grid">
      ${cats.map((c) => `
      <div class="cat-card" data-pcat="${escapeHtml(c)}">
        <div class="c-name"><span class="c-ico">${PICT_ICONS[c] || '✨'}</span>${escapeHtml(c)}</div>
        <span class="badge">${byCat[c].length} 词</span>
      </div>`).join('')}
    </div>`;
  view.querySelector('#back').onclick = back;
  view.querySelectorAll('.cat-card[data-pcat]').forEach((card) => {
    card.addEventListener('click', () => renderPictGrid(view, ctx, APP, tax, card.dataset.pcat));
  });
  view.scrollTop = 0;
}

function renderPictGrid(view, ctx, APP, tax, cat, page) {
  if (typeof page !== 'number' || page < 0) page = 0;
  const m = wordMap(APP);
  const isIconCat = cat === '图标简笔';
  const isMeanCat = cat === '义符';
  const inScopeW = (w) => { const ww = m.get(String(w).toLowerCase()); return !!ww && (!ctx.inScope || ctx.inScope(ww)); };
  const all = isIconCat
    ? Object.entries(tax.pictIcon || {}).filter(([w]) => m.has(w) && !tax.pict[w] && inScopeW(w))
        .sort((a, b) => ((m.get(a[0]).difficulty || 9) - (m.get(b[0]).difficulty || 9)) || a[0].localeCompare(b[0]))
    : Object.entries(tax.pict || {}).filter(([w, [, c]]) => c === cat && m.has(w) && inScopeW(w))
        .sort((a, b) => ((m.get(a[0]).difficulty || 9) - (m.get(b[0]).difficulty || 9)) || a[0].localeCompare(b[0]));
  const PAGE = 48;
  const totalPages = Math.max(1, Math.ceil(all.length / PAGE));
  if (page >= totalPages) page = totalPages - 1;
  const items = all.slice(page * PAGE, page * PAGE + PAGE);
  const shortMeaning = (w) => { const x = m.get(w); return ((x && x.meaning) || '').split(/[；;]/)[0]; };
  const imgHTML = (w, v) => {
    if (isIconCat) return iconSvg(v);                 // 图标简笔模块：保留 SVG 简笔（本身就是简笔画）
    const em = escapeHtml((v && v[0]) || '🔤');        // 表情图兜底
    // 精确助记图优先：vxiaozhi 每个单词的 AI 助记图像（按单词命名，对应精准），无图回退 emoji
    const url = vxImgURL(w);
    // 外层 .p-img-wrap 裁掉底部约 15%，去除源图右下角「小智晖的AI单词本」水印
    if (url) return `<span class="p-img-wrap"><img class="p-img" loading="lazy" alt="${escapeHtml(w)}" src="${escapeHtml(url)}" data-emoji="${em}"></span>`;
    // 无 vxiaozhi 图：回退 Unicode emoji（象形/义符类）
    return `<span class="p-e">${em}</span>`;
  };
  const pager = (pos) => `
    <div class="pager pager-${pos}">
      <button class="btn sm ghost" data-pg="prev" ${page <= 0 ? 'disabled' : ''}>‹ 上一页</button>
      <span class="pager-info">第 ${page + 1}/${totalPages} 页 · 共 ${all.length} 词</span>
      <button class="btn sm ghost" data-pg="next" ${page + 1 >= totalPages ? 'disabled' : ''}>下一页 ›</button>
    </div>`;
  view.innerHTML = `
    <div class="section-title">🧩象形记 · ${escapeHtml(cat)}（${all.length} 词）</div>
    <div class="card"><div class="between"><h2>${PICT_ICONS[cat] || '✨'} ${escapeHtml(cat)}</h2><button class="btn sm ghost" id="back">返回</button></div>
    <p class="hint" style="margin-top:4px">${isMeanCat ? '含义联想：用单词中文释义里的关键词配 emoji，建立图像关联（本地生成，不联网）。' : '点击任意词卡进入闪记；点「全部闪记」从该分类第一个词开始过词。单词优先显示 vxiaozhi AI 助记图（按词义精确生成），无图时回退 emoji。'}每页 ${PAGE} 词，可翻页浏览。</p></div>
    ${totalPages > 1 ? pager('top') : ''}
    <div class="pict-grid">
      ${items.map(([w, v]) => `
      <button class="pict-card" data-word="${escapeHtml(w)}">
        ${imgHTML(w, v)}
        <span class="p-w">${escapeHtml(w)}</span>
        <span class="p-m">${escapeHtml(shortMeaning(w).slice(0, 18))}</span>
      </button>`).join('')}
    </div>
    ${totalPages > 1 ? pager('bottom') : ''}
    <button class="btn block mt" id="allFlash">${IC.zapSm}全部闪记（${all.length} 词）</button>`;
  view.querySelector('#back').onclick = () => renderPictCats(view, ctx, APP, tax);
  const goPage = (p) => renderPictGrid(view, ctx, APP, tax, cat, p);
  view.querySelectorAll('[data-pg]').forEach((b) => b.addEventListener('click', () => {
    if (b.disabled) return;
    if (b.dataset.pg === 'prev') goPage(page - 1);
    else goPage(page + 1);
  }));
  view.querySelectorAll('.pict-card').forEach((b) => {
    b.addEventListener('click', () => {
      const i = all.findIndex(([x]) => x === b.dataset.word);
      const wordsAll = all.map(([x]) => m.get(x)).filter(Boolean);
      if (!wordsAll.length) return;
      // 以被点击的词为起点，打开整个小分类的闪记序列，使「上一张/下一张」能在分类内正常切换
      openCategory(view, ctx, `象形记 · ${cat}`, wordsAll, () => renderPictGrid(view, ctx, APP, tax, cat, 0), i >= 0 ? i : 0);
    });
  });
  // 真实语义照片加载失败 → 回退 emoji（表情图兜底）
  view.querySelectorAll('.p-img').forEach((img) => {
    img.addEventListener('error', function onErr() {
      const sp = document.createElement('span'); sp.className = 'p-e'; sp.textContent = img.dataset.emoji || '🔤';
      (img.closest('.p-img-wrap') || img).replaceWith(sp);
    });
  });
  view.querySelector('#allFlash').onclick = () => {
    const act = all.map(([w]) => m.get(w)).filter((w) => w && !isMastered(w.word) && ctx.inScope(w));
    if (!act.length) { ctx.toast('该分类在当前难度下暂无待练单词 🎉'); return; }
    openCategory(view, ctx, `象形记 · ${cat}`, act, () => renderPictGrid(view, ctx, APP, tax, cat, 0));
  };
  view.scrollTop = 0;
}

function openHSUnits(view, ctx, APP) {  const groups = hsUnitGroups(APP);
  const backToGrid = () => window.dispatchEvent(new CustomEvent('goto', { detail: 'category' }));
  view.innerHTML = `
    <div class="section-title">${IC.book}高中分单元记忆</div>
    <div class="card">
      <div class="between"><h2>按册 · 单元练习</h2><button class="btn sm ghost" id="back">返回分类</button></div>
      <p class="hint" style="margin-top:4px">点选某册下的单元，进入单词闪记与练习（已掌握的单词自动隐藏，遵循当前全局难度设置）。</p>
    </div>
    ${groups.map((bk) => `
      <div class="hs-book">
        <div class="hs-book-title">${IC.bookOpenSm}${escapeHtml(bk.units[0] ? bk.units[0].unit.replace(/U\d+$/, '').replace(/\s*Welcome\s*Unit$/i, '') : '') || '其他'}</div>
        <div class="cat-grid">
          ${bk.units.map((u) => {
            const all = u.words;
            const active = all.filter((w) => !isMastered(w.word) && ctx.inScope(w));
            const masteredCount = all.length - active.length;
            const badge = active.length ? `${active.length} 词待练` : '当前难度无待练';
            return `
            <div class="cat-card" data-unit="${escapeHtml(u.unit)}">
              <div class="c-name">${escapeHtml(u.unit)}</div>
              <div class="c-count">${all.length} 词${masteredCount ? ` · 已掌握 ${masteredCount}` : ''}</div>
              <span class="badge">${badge}</span>
            </div>`;
          }).join('')}
        </div>
      </div>
    `).join('')}
  `;
  view.querySelector('#back').onclick = backToGrid;
  view.querySelectorAll('.cat-card[data-unit]').forEach((card) => {
    card.addEventListener('click', () => {
      const unit = card.dataset.unit;
      const all = (APP.library.words || []).filter((w) => w.pep && w.pep.band === '高中' && w.pep.unit === unit);
      const active = all.filter((w) => !isMastered(w.word) && ctx.inScope(w));
      if (!active.length) { ctx.toast('该单元在当前难度下暂无待练单词 🎉'); return; }
      openCategory(view, ctx, unit, active, () => openHSUnits(view, ctx, APP));
    });
  });
}

function openCategory(view, ctx, title, words, onBack, startIdx) {
  let mode = 'flash'; // flash | quiz
  let idx = (typeof startIdx === 'number' && startIdx >= 0 && startIdx < words.length) ? startIdx : 0;

  function modeBar() {
    return `
      <div class="reading-mode-bar">
        <button class="mode-btn ${mode === 'flash' ? 'on' : ''}" data-mode="flash">${IC.zapSm}单词闪记</button>
        <button class="mode-btn ${mode === 'quiz' ? 'on' : ''}" data-mode="quiz">${IC.pencilSm}开始练习</button>
      </div>`;
  }
  function bindModeBar() {
    view.querySelectorAll('.mode-btn').forEach((b) => {
      b.addEventListener('click', () => {
        const m = b.dataset.mode;
        if (m === 'quiz') { runStudy(view, ctx, words, title); return; }
        mode = m; render();
      });
    });
  }

  function render() {
    if (mode === 'flash') return renderFlash();
    // quiz 交由 runStudy 接管视图
    runStudy(view, ctx, words, title);
  }

  function renderFlash() {
    const w = words[idx];
    view.innerHTML = `
      <div class="card">
        <div class="between"><h2><svg class="vico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3.5" y="3.5" width="7" height="7" rx="1.6"/><rect x="13.5" y="3.5" width="7" height="7" rx="1.6"/><rect x="3.5" y="13.5" width="7" height="7" rx="1.6"/><rect x="13.5" y="13.5" width="7" height="7" rx="1.6"/></svg>${escapeHtml(title)} · 单词闪记</h2><button class="btn sm ghost" id="back">返回</button></div>
        <div class="pill" style="margin-top:8px">${idx + 1} / ${words.length}</div>
        ${modeBar()}
      </div>
      <div class="flash-wrap">
        <button class="flash-arrow left" id="arrowPrev" aria-label="上一个">‹</button>
        <div id="flashCard"></div>
        <button class="flash-arrow right" id="arrowNext" aria-label="下一个">›</button>
      </div>
      <div class="row mt">
        <button class="btn gray block" id="prev">上一张</button>
        <button class="btn ghost block" id="next">下一张</button>
      </div>
      <button class="btn block mt" id="toQuiz">${IC.checkSm}开始练习</button>
    `;
    const wrap = view.querySelector('#flashCard');
    wrap.innerHTML = wordCardHTML(w, { showNote: true, fallbackEmoji: true });
    bindWordCardEvents(wrap, ctx);
    // 自动播放英式发音（{auto:true}：移动端未解锁/加载失败时静默，不弹报错）
    ctx.playUK(w.word, { auto: true });
    bindModeBar();
    const goPrev = () => { idx = (idx - 1 + words.length) % words.length; renderFlash(); };
    const goNext = () => { idx = (idx + 1) % words.length; renderFlash(); };
    view.querySelector('#prev').onclick = goPrev;
    view.querySelector('#next').onclick = goNext;
    const ap = view.querySelector('#arrowPrev'); if (ap) ap.onclick = goPrev;
    const an = view.querySelector('#arrowNext'); if (an) an.onclick = goNext;
    view.querySelector('#toQuiz').onclick = () => runStudy(view, ctx, words, title);
    view.querySelector('#back').onclick = onBack || (() => window.dispatchEvent(new CustomEvent('goto', { detail: 'category' })));
    // 切换卡片后回到顶部（而非停留在当前滚动位置）
    view.scrollTop = 0;
  }

  render();
}


// 听写记模块（原「快筛听写」）
// 模式：难度听（按 difficulty 本级/本级以下）/ 同步听（按人教版PEP 年级+单元）
// 顺序 / 随机；仅英音；自拼英文 + 中文10选1。
// 难度听：英文+中文一次全对 → 掌握；同步听：连续对 3 次 → 掌握，错则连击清零。

const DICT_DIFF_LABELS = { 1: '小学', 2: '初中', 3: '高中', 4: '四级', 5: '六级', 6: '考研', 7: 'GRE' };
const dictNormalizeInput = (s) => (s || '').toLowerCase().replace(/[\s'’]/g, '').trim();
// 人教版高中册顺序（用于单元排序）
const BOOK_ORDER = { 必修一: 0, 必修二: 1, 必修三: 2, 选必一: 3, 选必二: 4, 选必三: 5, 选必四: 6 };
// 单元排序键：Welcome Unit 置顶于所属册（单元号用 -1），其余按「册序 + 单元号」
function unitSortKey(u) {
  if (!u) return [99, 99];
  // 任一册的 Welcome Unit 都置于该册最前（如「必修一 Welcome Unit」「选必二 Welcome Unit」）
  const wm = /^(.+?)\s*Welcome\s*Unit$/i.exec(u);
  if (wm) return [BOOK_ORDER[wm[1]] != null ? BOOK_ORDER[wm[1]] : 99, -1];
  const m = /^([^U]+)U(\d+)$/.exec(u);
  if (!m) return [99, 99];
  return [BOOK_ORDER[m[1]] != null ? BOOK_ORDER[m[1]] : 99, Number(m[2])];
}

// 当天已听写单词（小写数组）：用于「每个单词每天只听写一轮」的防重复机制。
// 跨天自动重置；旧进度缺字段时回退空数组，绝不抛错。
function todayStr() { const d = new Date(); return d.getFullYear() + '-' + (d.getMonth() + 1) + '-' + d.getDate(); }
function todayDictated(APP) {
  const p = APP.progress;
  if (!p.dictatedLog || p.dictatedLog.date !== todayStr()) p.dictatedLog = { date: todayStr(), words: [] };
  if (!Array.isArray(p.dictatedLog.words)) p.dictatedLog.words = [];
  return p.dictatedLog.words;
}

const __mod_dictation = {
  render({ view, APP, ctx }) {
    // 注册「离开本模块」停播钩子：app.js 的 goto 在切换页面前调用，停止播报计时与自动跳转
    window.__hvDictStop = () => {
      stopAudio();
      if (autoTimer) { clearTimeout(autoTimer); autoTimer = null; }
    };
    const st = {
      mode: 'diff',                                   // diff | sync
      diffLevel: (APP.settings && APP.settings.difficulty) || 'all',   // 1..7 | 'all'
      diffScope: 'le',                                // 'eq' 仅本级 | 'le' 本级及以下
      syncBand: '小学',                               // 小学 | 初中 | 高中
      syncUnit: 'all',                                // 'all' | '必修一U1' ...
      order: 'seq',                                   // 'seq' 顺序 | 'rand' 随机
      cnt: 20, plays: 3, interval: 10,
      all: false,                                     // true=听写全部未掌握单词（本范围未听写/未掌握）
      allWords: false,                                // true=听写全部单词（本范围所有单词，含已掌握）
    };
    let words = [], idx = 0, masteredCnt = 0, wrongCnt = 0;
    const wrongWords = [];
    let playTimer = null;
    let autoTimer = null; // 全对后自动进入下一题的定时器
    let streakMap = {}; // 同步听：每词连续正确次数（顺序推进，不锁定同一词）
    let presented = 0;  // 已呈现单词计数
    let streak = 0;     // 当前单词的连击数（必须先声明：ESM 为严格模式，未声明赋值会抛 ReferenceError）

    function stopAudio() { if (playTimer) { clearTimeout(playTimer); playTimer = null; } }

    // 按 difficulty 过滤（独立于全局设置）；GRE 桶去重后的「有效难度」优先
    function matchDiff(w, lv, scope) {
      if (lv === 'all') return true;
      const d = (ctx && ctx.difficultyOf) ? ctx.difficultyOf(w) : w.difficulty;
      if (d == null) return false;
      const n = Number(lv);
      return scope === 'eq' ? d === n : d <= n;
    }

    // 取某年级下所有单元（去重，按册+单元排序）
    function unitsOf(band) {
      const set = new Set();
      for (const w of (APP.library.words || [])) {
        const p = w.pep;
        if (p && p.band === band && p.unit) set.add(p.unit);
      }
      const key = (u) => unitSortKey(u);
      return [...set].sort((a, b) => { const x = key(a), y = key(b); return x[0] - y[0] || x[1] - y[1]; });
    }

    // includeDictated=true 时不排除「当天已听写」单词（用于判断范围内是否还有单词可听写）
    function candidates(includeDictated) {
      let pool = (APP.library.words || []).filter((w) =>
        w.word && w.meaning && (st.allWords || !APP.progress.mastered[w.word.toLowerCase()]));
      // 词书范围：选中词书后仅保留词书内单词（与难度取交集）
      if (ctx && ctx.inScope) pool = pool.filter((w) => ctx.inScope(w));
      // 防重复：排除当天已经听写过的单词（每个单词每天只听写一轮）
      if (!includeDictated) {
        const done = todayDictated(APP);
        if (done.length) pool = pool.filter((w) => !done.includes(w.word.toLowerCase()));
      }
      if (st.mode === 'diff') {
        pool = pool.filter((w) => matchDiff(w, st.diffLevel, st.diffScope));
      } else {
        pool = pool.filter((w) => {
          const p = w.pep;
          if (!p || p.band !== st.syncBand) return false;
          if (st.syncUnit !== 'all' && p.unit !== st.syncUnit) return false;
          return true;
        });
        if (st.order === 'seq') {
          const key = (w) => {
            const p = w.pep || {};
            const sk = unitSortKey(p.unit || '');
            return [sk[0], sk[1], w.word];
          };
          pool = pool.slice().sort((a, b) => { const x = key(a), y = key(b); return x[0] - y[0] || x[1] - y[1] || (x[2] < y[2] ? -1 : 1); });
          return pool;
        }
      }
      return st.order === 'rand' ? shuffle(pool) : pool;
    }

    // 逐词标记「今天已听写」：仅在该单词真正被呈现（听到/作答）时记录。
    // 关键：不再于开轮时把整批单词一次性写入——否则中途退出时，未听到的词会被误吞，
    // 导致「当天没听过的单词」在听写模块里不再显示。返回 true 表示本次新增。
    function markDictated(w) {
      const lw = String(w && w.word ? w.word : w).toLowerCase();
      if (!lw) return false;
      const done = todayDictated(APP);
      if (done.includes(lw)) return false;
      done.push(lw);
      return true;
    }

    // 开始/再来一轮：取「当天未听写过」的候选词；「听写全部」时取本范围全部，否则按单词量截取。
    // 已在候选池中排除当天听写过的词；本轮单词在真正呈现时才逐词记为「今天已听写」。
    let pendingStart = false;  // 防止 core 未就绪时连点「开始」排队开两轮
    function beginRound() {
      stopAudio();
      // 词库「核心重字段」（释义）是分层懒加载的：还没到货时候选池会被 `w.meaning` 过滤成空，
      // 直接提示「没有可听写的单词」会误导用户 —— 先等数据到货再开轮（页面本身不阻塞）。
      if (APP.library && APP.library.__index && !APP._fullReady && ctx.ensureFull) {
        if (pendingStart) return;
        pendingStart = true;
        ctx.toast('词库详情加载中，马上开始…');
        ctx.ensureFull().then(() => {
          pendingStart = false;
          if (!window.APP || window.APP.page === 'dictation') beginRound();
        });
        return;
      }
      const allFull = candidates(true);   // 包含当天已听写的（用于判断范围内是否还有词）
      const all = candidates(false);       // 排除当天已听写的
      if (!allFull.length) {
        ctx.toast(st.mode === 'sync' ? '该年级/单元下没有可听写的单词' : '当前难度下没有可听写的单词');
        return;
      }
      if (!all.length) { renderAllDone(); return; }
      st.cnt = Math.max(5, Math.min(200, st.cnt));
      words = st.allWords ? allFull : (st.all ? all : all.slice(0, Math.max(1, st.cnt)));
      masteredCnt = 0; wrongCnt = 0; wrongWords.length = 0; streakMap = {};
      idx = 0; presented = 1;
      presentWord(words[idx], 0);
    }

    function renderConfig() {
      stopAudio();
      const levels = [['all', '全部（不限难度）']].concat([1, 2, 3, 4, 5, 6, 7].map((l) => [l, DICT_DIFF_LABELS[l]]));
      const diffOpts = levels.map(([lv, label]) =>
        `<label class="diff-opt"><input type="radio" name="df" value="${lv}" ${String(st.diffLevel) === String(lv) ? 'checked' : ''}> ${label}</label>`).join('');
      const unitOpts = ['<option value="all">全部单元</option>']
        .concat(unitsOf(st.syncBand).map((u) => `<option value="${escapeHtml(u)}" ${st.syncUnit === u ? 'selected' : ''}>${escapeHtml(u)}</option>`)).join('');
      const bandHint = st.syncBand !== '高中' && unitsOf(st.syncBand).length === 0
        ? '<p class="hint" style="margin-top:4px">该年级单元词表待导入，将按整个年级听写。</p>' : '';
      // 今日进度（逐词统计）：本范围未掌握总数 - 今天还没听写的 = 今天已听写
      const inScope = candidates(true).length;
      const remainCnt = candidates(false).length;
      const doneCnt = Math.max(0, inScope - remainCnt);

      view.innerHTML = `
        <div class="section-title">${IC.zap}听写记</div>
        <div class="card">
          <h2 style="margin-bottom:6px">听写设置</h2>
          <p class="hint">仅播放英式发音，需自行拼写英文，并从 10 个选项中选出中文释义。</p>

          <div class="field"><label>听写模式</label>
            <div class="seg">
              <button class="seg-btn ${st.mode === 'diff' ? 'on' : ''}" data-mode="diff">难度听</button>
              <button class="seg-btn ${st.mode === 'sync' ? 'on' : ''}" data-mode="sync">同步听</button>
            </div>
          </div>

          <div id="diffBox" style="${st.mode === 'diff' ? '' : 'display:none'}">
            <div class="field"><label>难度范围</label><div class="diff-opts">${diffOpts}</div></div>
            <div class="field" id="scopeBox" style="${st.diffLevel === 'all' ? 'display:none' : ''}"><label>范围方式</label>
              <div class="seg">
                <button class="seg-btn ${st.diffScope === 'eq' ? 'on' : ''}" data-scope="eq">仅本级</button>
                <button class="seg-btn ${st.diffScope === 'le' ? 'on' : ''}" data-scope="le">本级及以下</button>
              </div>
            </div>
          </div>

          <div id="syncBox" style="${st.mode === 'sync' ? '' : 'display:none'}">
            <div class="field"><label>年级（人教版PEP）</label>
              <div class="seg">
                <button class="seg-btn ${st.syncBand === '小学' ? 'on' : ''}" data-band="小学">小学</button>
                <button class="seg-btn ${st.syncBand === '初中' ? 'on' : ''}" data-band="初中">初中</button>
                <button class="seg-btn ${st.syncBand === '高中' ? 'on' : ''}" data-band="高中">高中</button>
              </div>
            </div>
            <div class="field"><label>单元</label>
              <select id="syncUnit" class="typing">${unitOpts}</select>
            </div>
            ${bandHint}
          </div>

          <div class="field"><label>听写顺序</label>
            <div class="seg">
              <button class="seg-btn ${st.order === 'seq' ? 'on' : ''}" data-order="seq">顺序</button>
              <button class="seg-btn ${st.order === 'rand' ? 'on' : ''}" data-order="rand">随机</button>
            </div>
          </div>

          <div class="field"><label class="chk"><input type="checkbox" id="allWordsChk" ${st.allWords ? 'checked' : ''}> 听写全部单词（本范围所有单词，含已掌握）</label></div>
          <div class="field"><label class="chk"><input type="checkbox" id="allChk" ${st.all ? 'checked' : ''}> 听写全部未掌握单词（本范围所有未听写、未掌握的单词）</label></div>
          <div class="field"><label>听写单词量</label><input type="number" class="typing" id="cnt" value="${st.cnt}" min="5" max="200" ${(st.all || st.allWords) ? 'disabled' : ''}></div>
          <div class="field"><label>每个单词播报次数</label><input type="number" class="typing" id="plays" value="${st.plays}" min="1" max="6"></div>
          <div class="field"><label>播报间隔（秒）</label><input type="number" class="typing" id="iv" value="${st.interval}" min="1" max="10"></div>
          <p class="hint" style="margin-top:-2px">今日本范围：已听写 <b>${doneCnt}</b> 词 · 剩余可听写 <b>${remainCnt}</b> 词。限制按<b>单词</b>逐词记录（与模块执行次数无关）——听过的词今天不再出现，没听过的词正常出现。</p>

          <button class="btn block mt" id="start">${IC.playSm}开始听写</button>
        </div>`;

      // 模式切换
      view.querySelectorAll('[data-mode]').forEach((b) => b.onclick = () => { st.mode = b.dataset.mode; renderConfig(); });
      view.querySelectorAll('[data-scope]').forEach((b) => b.onclick = () => { st.diffScope = b.dataset.scope; renderConfig(); });
      view.querySelectorAll('[data-band]').forEach((b) => b.onclick = () => { st.syncBand = b.dataset.band; st.syncUnit = 'all'; renderConfig(); });
      view.querySelectorAll('[data-order]').forEach((b) => b.onclick = () => { st.order = b.dataset.order; renderConfig(); });
      view.querySelectorAll('input[name="df"]').forEach((r) => r.onchange = () => {
        st.diffLevel = r.value;
        const sb = view.querySelector('#scopeBox');
        if (sb) sb.style.display = st.diffLevel === 'all' ? 'none' : '';
      });
      const su = view.querySelector('#syncUnit');
      if (su) su.onchange = () => { st.syncUnit = su.value; };
      const allChk = view.querySelector('#allChk');
      if (allChk) allChk.onchange = () => { st.all = allChk.checked; renderConfig(); };
      const allWordsChk = view.querySelector('#allWordsChk');
      if (allWordsChk) allWordsChk.onchange = () => { st.allWords = allWordsChk.checked; if (st.allWords) st.all = false; renderConfig(); };
      const bindNum = (id, key) => { const el = view.querySelector('#' + id); if (el) el.oninput = () => { st[key] = parseInt(el.value, 10) || st[key]; }; };
      bindNum('cnt', 'cnt'); bindNum('plays', 'plays'); bindNum('iv', 'interval');

      view.querySelector('#start').onclick = () => beginRound();
    }

    function playSeries(word, n, interval) {
      stopAudio();
      let i = 0;
      const step = () => {
        if (i >= n) { playTimer = null; return; }
        ctx.playUK(word, { auto: true });
        i++;
        if (i < n) playTimer = setTimeout(step, interval * 1000);
      };
      step();
    }

    function presentWord(w, curStreak) {
      streak = curStreak;
      // 逐词精确记录：该单词此刻真正呈现（听到/作答）后才算「今天已听写」
      if (markDictated(w)) ctx.saveProgress();
      // 中文正确释义：与「高中同步词表」（单元闪记 wordCardHTML）显示的中文释义完全一致，
      // 使用 plainMeaning（取前 3 个义项），而非 commonMeaning 仅取首义项，避免两者不一致。
      const pool = words.filter((x) => x.word !== w.word && plainMeaning(x.meaning));
      const options = buildEn2ZhOptions(w.meaning, pool, 10, true);
      const answerZh = plainMeaning(w.meaning) || w.meaning;
      let chosenZh = null;
      const isSync = st.mode === 'sync';
      const remaining = words.filter((x) => !APP.progress.mastered[x.word.toLowerCase()]).length;
      const progLabel = isSync
        ? `已掌握 <b>${masteredCnt}</b> · 待掌握 <b>${remaining}</b>`
        : `单词 ${idx + 1} / ${words.length}`;
      const streakPill = isSync
        ? `<span class="stat-pill ${streak >= 2 ? 'ok' : 'warn'}">连击 ${streak}/3</span>` : '';
      view.innerHTML = `
        <div class="card">
          <div class="between"><h2>${IC.zap}听写</h2><span class="pill">${progLabel}</span></div>
          <div class="dictate-status">
            <span class="stat-pill ok">掌握 <b>${masteredCnt}</b></span>
            <span class="stat-pill warn">未掌握 <b>${wrongCnt}</b></span>
            ${streakPill}
          </div>
          <div class="dictate-audio">
            <button class="audio-btn big" id="replay" title="重播英音">${IC.volumeSm}重播</button>
            <span class="hint">${isSync ? '同步听：连续拼对 3 次才判定掌握，错一次连击清零。' : '正在播放英式发音…'}</span>
          </div>
          <div class="field"><label>拼写英文</label><input type="text" class="typing" id="en" placeholder="输入听到的单词" autocomplete="off" autocorrect="off" spellcheck="false"></div>
          <div class="hint">选择中文释义（10 选 1）：</div>
          <div id="opts" class="opts-grid">${options.map((o, i) => `<button class="opt" data-i="${i}">${escapeHtml(o)}</button>`).join('')}</div>
          <div id="explain" class="example mt" style="display:none"></div>
        </div>
        <button class="btn block mt" id="submit">提交</button>
        ${isSync ? '<button class="btn gray block mt" id="skip">跳过本题</button>' : ''}`;
      view.querySelector('#replay').onclick = () => playSeries(w.word, st.plays, st.interval);
      const input = view.querySelector('#en');
      input.focus();
      playSeries(w.word, st.plays, st.interval);
      const opts = view.querySelectorAll('.opt');
      opts.forEach((b) => b.addEventListener('click', () => {
        if (chosenZh !== null) return;
        chosenZh = options[+b.dataset.i];
        opts.forEach((x) => { x.disabled = true; if (options[+x.dataset.i] === answerZh) x.classList.add('correct'); else if (x === b) x.classList.add('wrong'); });
        check(w);
      }));
      function check(wd) {
        const enOk = dictNormalizeInput(input.value) === dictNormalizeInput(wd.word);
        const zhOk = chosenZh === answerZh;
        const exp = view.querySelector('#explain');
        exp.style.display = 'block';
        const submit = view.querySelector('#submit');
        // 全对：展示反馈后自动进入下一题（点击按钮/回车可立即跳过等待）；做错：手动点「下一题 →」
        const scheduleAuto = () => {
          if (autoTimer) clearTimeout(autoTimer);
          autoTimer = setTimeout(() => { autoTimer = null; advance(); }, 1200);
        };
      if (isSync) {
        if (enOk && zhOk) {
          const s = (streakMap[wd.word] || 0) + 1;
          streakMap[wd.word] = s;
          if (s >= 3) {
            masteredCnt++;
            ctx.markMastered(wd.word);
            exp.innerHTML = IC.checkSm + '连续 3 次正确，已掌握 ' + escapeHtml(wd.word) + '！+10星';
          } else {
            exp.innerHTML = IC.checkSm + '正确（连续 ' + s + '/3），即将进入下一个单词…';
          }
          submit.textContent = (masteredCnt >= words.length) ? '完成' : '下一题 →';
          submit.onclick = advance;
          scheduleAuto();
        } else {
          streakMap[wd.word] = 0;
          wrongCnt++;
          if (!wrongWords.includes(wd.word)) wrongWords.push(wd.word);
          ctx.recordWrongAnswer(wd.word, false);
          const tips = [];
          if (!enOk) tips.push('英文应为 ' + escapeHtml(wd.word));
          if (!zhOk) tips.push('正确中文：' + escapeHtml(answerZh));
          exp.innerHTML = IC.xSm + '连击清零。' + tips.join('；');
          submit.textContent = '下一题 →';
          submit.onclick = advance;
        }
      } else {
        if (enOk && zhOk) {
          masteredCnt++;
          ctx.markMastered(wd.word);
          exp.innerHTML = IC.checkSm + '英文与中文都答对，已掌握 ' + escapeHtml(wd.word) + '！+10星';
          scheduleAuto();
        } else {
          wrongCnt++;
          if (!wrongWords.includes(wd.word)) wrongWords.push(wd.word);
          ctx.recordWrongAnswer(wd.word, false);
          const tips = [];
          if (!enOk) tips.push('英文应为 ' + escapeHtml(wd.word));
          if (!zhOk) tips.push('正确中文：' + escapeHtml(answerZh));
          exp.innerHTML = IC.xSm + tips.join('；');
        }
        submit.textContent = idx < words.length - 1 ? '下一题 →' : '完成';
        submit.onclick = advance;
      }
      }
      if (isSync) {
        const skip = view.querySelector('#skip');
        if (skip) skip.onclick = () => { streakMap[w.word] = 0; advance(); };
      }
      input.addEventListener('keydown', (e) => { if (e.key === 'Enter' && chosenZh !== null) (view.querySelector('#submit').onclick || function () {}).call(); });
      view.querySelector('#submit').onclick = () => { ctx.toast('请先选择中文释义'); };
    }

    // 只向前扫描：本轮每个候选词各呈现一次，到末尾即完成，绝不回绕（回绕会导致答错的词永远不被掌握而无限循环）。
    function nextUnmastered(from) {
      if (!words.length) return -1;
      for (let i = from; i < words.length; i++) {
        if (!APP.progress.mastered[words[i].word.toLowerCase()]) return i;
      }
      return -1;
    }
    function advance() {
      if (autoTimer) { clearTimeout(autoTimer); autoTimer = null; } // 手动/定时二选一，防止连跳两题
      const ni = nextUnmastered(idx + 1);
      if (ni < 0) { renderDone(); return; }
      idx = ni; presented++;
      presentWord(words[idx], streakMap[words[idx].word] || 0);
    }

    function renderDone() {
      stopAudio();
      if (autoTimer) { clearTimeout(autoTimer); autoTimer = null; }
      ctx.completeSession(words, new Set(wrongWords));
      window.dispatchEvent(new CustomEvent('dictation-complete'));
      const modeHint = st.mode === 'sync'
        ? '同步听：需连续拼对 3 次才判定掌握，错一次连击清零。'
        : '难度听：英文与中文一次全对即判定掌握。';
      const wbCount = (APP.progress.wrongBook || []).filter((w) =>
        !(APP.progress.mastered && APP.progress.mastered[String(w).toLowerCase()])).length;
      view.innerHTML = `
        <div class="card" style="text-align:center">
          <h2>${IC.checkSm}听写完成！</h2>
          <div class="stat-grid">
            <div class="stat"><div class="num">${words.length}</div><div class="lab">听写单词</div></div>
            <div class="stat"><div class="num ok">${masteredCnt}</div><div class="lab">已掌握</div></div>
            <div class="stat"><div class="num warn">${wrongCnt}</div><div class="lab">未掌握</div></div>
          </div>
          <p class="hint mt">${modeHint}</p>
          <p class="hint">本轮<b>实际听过</b>的单词已逐词记录，今天不再出现；未听到的单词下次仍会正常出现。</p>
          ${wrongWords.length ? `<p class="hint">未掌握的 <b>${wrongWords.length}</b> 个单词已自动进入「错词本」，建议去错词本复习。</p>` : ''}
          <button class="btn block mt" id="again">${IC.rotateSm}再来一轮（听写未听写的单词）</button>
          ${wrongWords.length ? `<button class="btn warn block mt" id="wb">${IC.bookXSm}去错词本复习错词（${wrongWords.length}）</button>` : ''}
          <button class="btn gray block mt" id="back">返回设置</button>
        </div>`;
      view.querySelector('#again').onclick = () => beginRound();
      view.querySelector('#back').onclick = () => renderConfig();
      const wbBtn = view.querySelector('#wb');
      if (wbBtn) wbBtn.onclick = () => window.dispatchEvent(new CustomEvent('goto', { detail: 'wrongbook' }));
    }

    // 当天范围内所有单词都已听写过：不再重复，引导去错词本复习
    function renderAllDone() {
      stopAudio();
      if (autoTimer) { clearTimeout(autoTimer); autoTimer = null; }
      window.dispatchEvent(new CustomEvent('dictation-complete'));
      const wbCount = (APP.progress.wrongBook || []).filter((w) =>
        !(APP.progress.mastered && APP.progress.mastered[String(w).toLowerCase()])).length;
      view.innerHTML = `
        <div class="card" style="text-align:center">
          <h2>${IC.checkSm}今天的单词都听写过了</h2>
          <p class="hint mt">听写记用于快速筛选你已掌握的单词，<b>每个单词每天只听写一轮</b>。当前筛选范围内的单词今天都已听写过，不再重复。</p>
          ${wbCount ? `<p class="hint">还有 <b>${wbCount}</b> 个错词在「错词本」里，建议去专项复习巩固。</p>` : '<p class="hint">错词本已清空，非常棒！</p>'}
          <button class="btn block mt" id="wb">${IC.bookXSm}去错词本复习</button>
          <button class="btn gray block mt" id="back">返回设置</button>
        </div>`;
      view.querySelector('#wb').onclick = () => window.dispatchEvent(new CustomEvent('goto', { detail: 'wrongbook' }));
      view.querySelector('#back').onclick = () => renderConfig();
    }

    renderConfig();
  },
};



const __mod_import = {
  render({ view, APP, ctx }) {
    view.innerHTML = `
      <div class="section-title">${IC.upload}单词导入 · 入库强校验</div>
      <div class="card">
        <h2>① 批量结构化导入（Workbuddy 识别输出）</h2>
        <div class="hint">
          支持 JSON 数组：<br/>
          <code>[{ "word":"happy", "meaning":"adj.快乐的", "example":"She is happy.", "exampleCn":"她很快乐。", "phoneticUk":"/ˈhæpi/", "category":"情绪" }]</code><br/>
          也支持 制表符/逗号 文本：<code>happy\tadj.快乐的\tShe is happy.\t她很快乐。</code>
        </div>
        <textarea id="src" rows="8" placeholder="在此粘贴 JSON 或文本…"></textarea>
        <div class="row mt">
          <button class="btn ghost" id="pick">${IC.fileTextSm}选择文件</button>
          <input type="file" id="file" accept=".json,.csv,.txt" style="display:none" />
          <button class="btn" id="check">${IC.eyeSm}校验预览</button>
        </div>
        <div id="report" class="report mt" style="display:none"></div>
        <button class="btn block mt" id="doImport" style="display:none">${IC.checkSm}确认入库（仅合格数据）</button>
      </div>

      <div class="card">
        <h2>② 自定义单词（自动补全全套词典信息）</h2>
        <div class="hint">每行一个单词，系统调用有道自动补全音标/释义/例句，再经校验入库（≤50 词/次）。</div>
        <textarea id="words" rows="5" placeholder="apple&#10;banana&#10;computer"></textarea>
        <button class="btn soft block mt" id="autoFill">${IC.zapSm}自动补全并入库</button>
        <div id="autoReport" class="report mt" style="display:none"></div>
      </div>
    `;

    const $ = (s) => view.querySelector(s);
    $('#pick').onclick = () => $('#file').click();
    $('#file').onchange = async (e) => {
      const f = e.target.files[0]; if (!f) return;
      const txt = await f.text();
      $('#src').value = txt;
      ctx.toast('已读取文件，点击校验预览');
    };
    $('#check').onclick = () => {
      const raw = parseInput($('#src').value);
      if (!raw.length) { ctx.toast('没有可解析的内容'); return; }
      const report = window.ValidatorCore.run(raw);
      renderReport($('#report'), report);
      $('#report').style.display = 'block';
      $('#doImport').style.display = 'block';
      $('#doImport').dataset.payload = JSON.stringify(report.passed);
    };
    $('#doImport').onclick = async () => {
      const passed = JSON.parse($('#doImport').dataset.payload || '[]');
      const r = await safeFetch('/api/import', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ words: passed }),
      });
      const j = await r.json();
      ctx.toast('入库完成，新增 ' + (j.added ?? 0) + ' 词');
      // 重新加载词库
      const lib = await (await safeFetch('/api/library')).json();
      APP.library = lib;
      ctx.refreshHeader();
    };

    $('#autoFill').onclick = async () => {
      const lines = $('#words').value.split(/\n+/).map((s) => s.trim()).filter(Boolean).slice(0, 50);
      if (!lines.length) { ctx.toast('请输入单词'); return; }
      const rep = $('#autoReport'); rep.style.display = 'block'; rep.innerHTML = '⏳ 正在调用有道补全（' + lines.length + ' 词）…';
      const recs = [];
      for (const w of lines) {
        try {
          const r = await safeFetch('/api/dict?word=' + encodeURIComponent(w));
          const j = await r.json();
          const d = j.data;
          if (d && (d.pos.length || d.phonetic)) {
            const meaning = d.pos.map((p) => p.pos + ' ' + p.def).join('；') || d.phonetic;
            recs.push({ word: w, meaning, example: d.examples[0]?.en || '', exampleCn: d.examples[0]?.cn || '', phoneticUk: d.uk, phoneticUs: d.us });
          } else {
            recs.push({ word: w, meaning: '（有道未返回，需手动补充）', example: '', exampleCn: '' });
          }
        } catch (e) {
          recs.push({ word: w, meaning: '（网络异常）', example: '', exampleCn: '' });
        }
      }
      const report = window.ValidatorCore.run(recs);
      renderReport(rep, report);
      const r = await safeFetch('/api/import', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ words: report.passed }) });
      const j = await r.json();
      ctx.toast('自动补全入库完成，新增 ' + (j.added ?? 0) + ' 词');
      const lib = await (await safeFetch('/api/library')).json();
      APP.library = lib;
      ctx.refreshHeader();
    };
  },
};

function parseInput(text) {
  text = (text || '').trim();
  if (!text) return [];
  // 尝试 JSON
  if (text.startsWith('[') || text.startsWith('{')) {
    try { const j = JSON.parse(text); return Array.isArray(j) ? j : (j.words || []); } catch (e) { /* fallthrough */ }
  }
  // 文本：按行，按制表符/逗号分列
  const lines = text.split(/\n+/).map((l) => l.trim()).filter(Boolean);
  const out = [];
  for (const line of lines) {
    const parts = line.split(/\t|[,，]/).map((s) => s.trim());
    if (parts.length >= 2) {
      out.push({ word: parts[0], meaning: parts[1], example: parts[2] || '', exampleCn: parts[3] || '', category: parts[4] || '' });
    } else if (parts.length === 1) {
      out.push({ word: parts[0], meaning: '', example: '', exampleCn: '' });
    }
  }
  return out;
}

function renderReport(el, report) {
  const s = report.stats;
  el.innerHTML = `
    <div class="r-row"><span>总记录</span><b>${report.total}</b></div>
    <div class="r-row r-ok"><span>${IC.checkSm}合格入库</span><b>${s.passed}</b></div>
    <div class="r-row r-bad"><span>${IC.alertSm}疑似粘连错词</span><b>${s.stuck}</b></div>
    <div class="r-row r-bad"><span>${IC.alertSm}字段残缺</span><b>${s.incomplete}</b></div>
    <div class="r-row r-bad"><span>${IC.alertSm}脏数据/空</span><b>${s.dirty}</b></div>
    <div class="r-row r-bad"><span>${IC.alertSm}重复</span><b>${s.duplicate}</b></div>
    ${report.log.stuckList.length ? `<div class="hint mt">粘连疑似词：${escapeHtml(report.log.stuckList.join(', '))}</div>` : ''}
    ${report.log.incompleteList.length ? `<div class="hint">残缺词：${escapeHtml(report.log.incompleteList.join(', '))}</div>` : ''}
    <div class="hint mt">仅合格数据入库，异常数据已拦截，请人工修正后重新导入。</div>
  `;
}


// 听力训练模块
// 3 套 2024 高考英语听力真题，提供三种训练模式：
//   1. 实战模考：完整播放，按 1-20 题顺序作答，整卷评分
//   2. 精听训练：分题听 + 立即看原文/答案/解析
//   3. 原文跟读：听原声后影子跟读（shadowing），录音评分训练语感
// 顶部常显「考场 5 招」策略卡（高考英语听力技巧 + 抖音 @九九老师方法论）

const STRATEGIES = [
  { icon: IC.eyeSm, title: '听前抢读', tip: '发卷后立刻圈出题干疑问词、性别、地点、时间；选项对比找差异（同义/相反），大概率答案就在那对里。' },
  { icon: IC.targetSm, title: '抓主旨', tip: '长对话/独白的「首句 → 主旨」「尾句 → 结论/态度」「but/however 后 → 90% 是答案」。' },
  { icon: IC.pencilSm, title: '速记关键', tip: '数字、时间、地址、人名必须动笔记；听到原价+打折价时只记尾数，要做简单加减。' },
  { icon: IC.xSm, title: '果断不纠结', tip: '听力不可逆。一道没听清立刻放弃，盯住下一题；女士的建议/最后出现的信息往往是答案。' },
  { icon: IC.starSm, title: '蒙题偏好', tip: '选委婉/有礼貌/积极的；避开 only/must/never 等绝对词；同义替换比照读更可能是答案。' },
];

// 共享 audio 元素：模块内单实例，离开模块时停止
let _audio = null;
function getAudio() {
  if (!_audio) {
    _audio = new Audio();
    _audio.preload = 'metadata';
    _audio.id = 'lstAudio';
    // 挂到 DOM：部分浏览器（尤其 iOS Safari）对游离 audio 的播放控制更严格
    document.body.appendChild(_audio);
  }
  return _audio;
}
function stopAudio() {
  if (_audio) { _audio.pause(); _audio.currentTime = 0; }
  stopPrecisePlay();
}

// 毫秒级精准截断播放：用 requestAnimationFrame 轮询 audio.currentTime 并在越过 gEnd 时立即暂停，
// 配合 setTimeout 兜底（标签页后台休眠时 rAF 不触发）。相比 timeupdate（~250ms 粒度），
// 截断误差降到一帧（~16ms）以内，短句不再溢出到下一句。
let _segRaf = null;
let _segTo = null;
function stopPrecisePlay() {
  if (_segRaf) { cancelAnimationFrame(_segRaf); _segRaf = null; }
  if (_segTo) { clearTimeout(_segTo); _segTo = null; }
}
// 精确播放 [start, end] 区间（单位：秒，支持小数）。onStop 在暂停后回调。
function playSegmentPrecise(start, end, onStop) {
  stopPrecisePlay();
  const audio = getAudio();
  try { audio.currentTime = start; } catch (e) {}
  const pr = audio.play();
  if (pr && pr.catch) pr.catch(() => {});
  const durMs = Math.max(0, (end - start)) * 1000;
  let stopped = false;
  const doStop = () => {
    if (stopped) return;
    stopped = true;
    stopPrecisePlay();
    try { audio.pause(); } catch (e) {}
    if (onStop) onStop();
  };
  const tick = () => {
    if (stopped) return;
    // 越过 end 立即暂停；-0.02 预留一帧余量
    if (audio.currentTime >= end - 0.02) { doStop(); return; }
    _segRaf = requestAnimationFrame(tick);
  };
  // 等真正开始播放后再启动 rAF 轮询，避免 seek 延迟导致提前判定
  const onPlay = () => { _segRaf = requestAnimationFrame(tick); audio.removeEventListener('playing', onPlay); };
  audio.addEventListener('playing', onPlay);
  // 兜底：即便 rAF 被节流，也在理论时长 + 缓冲后强制停止
  _segTo = setTimeout(doStop, durMs + 500);
}

// 题库懒加载
let _papers = null;
let _loading = null;
async function loadPapers() {
  if (_papers && Object.keys(_papers).length) return _papers;
  if (_loading) return _loading;
  _loading = (async () => {
    let last = {};
    for (let i = 0; i < 3; i++) {
      try {
        const r = await safeFetch('/api/listening');
        if (r.ok) {
          const d = await r.json();
          if (d && Object.keys(d).length) { _papers = d; return d; }
          last = d || {};
        }
      } catch (e) { /* 网络抖动重试 */ }
      await new Promise((res) => setTimeout(res, 300));
    }
    _papers = last;
    return last;
  })();
  _loading.finally(() => { _loading = null; });
  return _loading;
}

// 进度辅助
function getProgress(paperId) {
  if (!APP.progress || typeof APP.progress !== 'object') APP.progress = { listening: { history: {}, wrong: {}, best: {} } };
  const p = APP.progress;
  if (!p.listening || typeof p.listening !== 'object') p.listening = { history: {}, wrong: {}, best: {} };
  if (!p.listening.history || typeof p.listening.history !== 'object') p.listening.history = {};
  if (!p.listening.wrong || typeof p.listening.wrong !== 'object') p.listening.wrong = {};
  if (!p.listening.best || typeof p.listening.best !== 'object') p.listening.best = {};
  if (!p.listening.history[paperId]) p.listening.history[paperId] = [];
  if (!p.listening.wrong[paperId]) p.listening.wrong[paperId] = [];
  return {
    history: p.listening.history[paperId],
    wrong: p.listening.wrong[paperId],
    best: p.listening.best[paperId] || 0,
  };
}
function saveHistory(paperId, mode, score, total, wrongList) {
  if (!APP.progress || typeof APP.progress !== 'object') APP.progress = { listening: { history: {}, wrong: {}, best: {} } };
  const p = APP.progress;
  if (!p.listening || typeof p.listening !== 'object') p.listening = { history: {}, wrong: {}, best: {} };
  if (!p.listening.history[paperId]) p.listening.history[paperId] = [];
  if (!p.listening.wrong[paperId]) p.listening.wrong[paperId] = [];
  const d = new Date();
  const date = d.getFullYear() + '-' + (d.getMonth() + 1) + '-' + d.getDate() + ' ' + d.getHours() + ':' + String(d.getMinutes()).padStart(2, '0');
  p.listening.history[paperId].push({ date, mode, score, total, wrong: wrongList });
  if (score > (p.listening.best[paperId] || 0)) p.listening.best[paperId] = score;
  // 错题累加
  for (const n of wrongList) {
    if (!p.listening.wrong[paperId].includes(n)) p.listening.wrong[paperId].push(n);
  }
  if (window.APP && window.APP.progress === p) {
    if (typeof saveProgress === 'function') saveProgress();
  }
}

function fmtDuration(sec) {
  if (!sec) return '—';
  const m = Math.floor(sec / 60);
  const s = Math.round(sec % 60);
  return m + '\'' + String(s).padStart(2, '0') + '"';
}
// 毫秒级时间显示：在秒后附加一位小数（如 4'19.8"–4'20.7"），让短句边界一目了然
function fmtMs(sec) {
  if (sec == null || isNaN(sec)) return '—';
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  const cs = Math.round((sec - Math.floor(sec)) * 10);
  return m + '\'' + String(s).padStart(2, '0') + (cs ? '.' + cs : '') + '"';
}

